<?php $pageTitle='Biblioteca de máquinas';require __DIR__.'/partials/header.php'; ?>
<div class="page-heading"><div><p class="overline"><i></i> Planejamento</p><h1>Biblioteca de máquinas</h1><p>Pré-cadastre modelos por ramo industrial e use suas estruturas ao cadastrar ativos.</p></div><button class="button" data-open="new-model"><?= ico('plus',18) ?> Novo modelo</button></div>
<form method="get" class="filters"><input type="hidden" name="route" value="biblioteca"><label>Buscar modelo<input name="q" placeholder="Modelo, fabricante ou TAG" value="<?= h($q) ?>"></label>
<label>Segmento industrial<select name="segment"><option value="0">Todos os segmentos</option><?php foreach($segments as $s): ?><option value="<?= $s['id_segmento'] ?>" <?= (int)$s['id_segmento']===$segment?'selected':'' ?>><?= h($s['nome']) ?><?= (int)$s['id_segmento']===$who['segment']?' · Sua indústria':'' ?></option><?php endforeach; ?></select></label><button class="button secondary">Filtrar</button></form>
<div class="asset-grid"><?php foreach($machines as $m): ?><article class="paper asset-card library-card"><div class="card-top"><span class="symbol"><?= ico('book',24) ?></span><?= refTag($m['tag']) ?></div><p class="maker"><?= h($m['fabricante']?:'Fabricante não informado') ?></p><h2><?= h($m['modelo']) ?></h2><p><?= h($m['descricao']) ?></p><div class="card-end"><span><?= h($m['segmentos']) ?></span><a class="link" href="<?= h(url('biblioteca',['id'=>$m['id_maquina_biblioteca'],'segment'=>$segment,'q'=>$q])) ?>">Abrir modelo</a></div></article><?php endforeach; ?></div>
<?php if(!$machines): ?><p class="paper empty">Nenhum modelo neste filtro. Você pode pré-cadastrar um modelo para o seu segmento.</p><?php endif; ?>
<dialog id="new-model" aria-labelledby="model-title" <?= $error&&$action!=='install'?'data-reopen':'' ?>><div class="dialog-head"><h2 id="model-title">Pré-cadastrar modelo</h2><button class="icon-button" data-close aria-label="Fechar"><?= ico('close') ?></button></div>
<form class="dialog-form" method="post" action="<?= url('biblioteca') ?>"><?= csrfField() ?><input type="hidden" name="action" value="create">
<?php if($error&&$action!=='install'): ?><p class="alert" role="alert"><?= h($error) ?></p><?php endif; ?>
<label>Nome do modelo<input required name="modelo" maxlength="120" value="<?= h($_POST['modelo']??'') ?>"></label><div class="two-fields"><label>TAG de referência<input name="tag" maxlength="50" value="<?= h($_POST['tag']??'') ?>"></label><label>Fabricante<select name="fabricante"><option value="">Não informado</option><?php foreach($makers as $f): ?><option value="<?= $f['id_fabricante'] ?>" <?= $f['id_fabricante']==($_POST['fabricante']??'')?'selected':'' ?>><?= h($f['nome']) ?></option><?php endforeach; ?></select></label></div>
<fieldset><legend>Segmentos industriais</legend><?php foreach($segments as $s): ?><label class="checkbox"><input type="checkbox" name="segmentos[]" value="<?= $s['id_segmento'] ?>" <?= in_array($s['id_segmento'],$_POST['segmentos']??[$who['segment']])?'checked':'' ?>><?= h($s['nome']) ?></label><?php endforeach; ?></fieldset>
<label>Descrição <small>(opcional)</small><textarea name="descricao" rows="3"><?= h($_POST['descricao']??'') ?></textarea></label><div class="dialog-actions"><button class="button secondary" type="button" data-close>Cancelar</button><button class="button">Salvar modelo</button></div></form></dialog>
<?php if($selected): $m=$selected;$structures=[];foreach($templates as $t)$structures[$t['id_template']]=$t['nome']; ?>
<dialog id="model-detail" aria-labelledby="detail-title" data-reopen><div class="dialog-head"><?= refTag($m['tag']) ?><button class="icon-button" data-close aria-label="Fechar"><?= ico('close') ?></button></div><h2 id="detail-title"><?= h($m['modelo']) ?></h2><p><?= h($m['fabricante']) ?></p>
<h3>Estruturas e componentes</h3><?php foreach($structures as $tid=>$structure): ?><strong><?= h($structure) ?></strong><ul class="parts"><?php foreach($templates as $t): if($t['id_template']==$tid && $t['componente']!==null): ?><li><?= (int)$t['quantidade'] ?> × <?= h($t['componente']) ?><?= $t['vida_util']?' · '.number_format($t['vida_util'],0,',','.').' h':'' ?></li><?php endif;endforeach; ?></ul><?php endforeach; ?>
<?php if(!$structures): ?><p>Modelo sem estrutura de componentes cadastrada.</p><?php endif; ?>
<?php if($compatible && $lines): ?><hr><h3>Cadastrar ativo deste modelo</h3><form method="post" class="dialog-form"><?= csrfField() ?><input type="hidden" name="action" value="install">
<?php if($error&&$action==='install'): ?><p class="alert" role="alert"><?= h($error) ?></p><?php endif; ?>
<label>Nome do ativo<input name="nome" required maxlength="120" value="<?= h($_POST['nome']??$m['modelo']) ?>"></label><div class="two-fields"><label>TAG do ativo<input name="tag" required maxlength="50" placeholder="Ex. MQ-LAM-02" value="<?= h($_POST['tag']??'') ?>"></label><label>Criticidade<select name="criticidade"><?php foreach(['baixa','media','alta','critica'] as $v): ?><option value="<?= $v ?>" <?= $v===($_POST['criticidade']??'media')?'selected':'' ?>><?= h(labelOf($v)) ?></option><?php endforeach; ?></select></label></div>
<label>Linha de produção<select name="linha" required><option value="">Selecione a linha</option><?php foreach($lines as $l): ?><option value="<?= $l['id_linha'] ?>" <?= $l['id_linha']==($_POST['linha']??'')?'selected':'' ?>><?= h($l['setor'].' · '.$l['nome']) ?></option><?php endforeach; ?></select></label>
<label>Condição operacional<select name="status"><?php foreach(['operando','parada','em_manutencao','desativada'] as $v): ?><option value="<?= $v ?>" <?= $v===($_POST['status']??'operando')?'selected':'' ?>><?= h(labelOf($v)) ?></option><?php endforeach; ?></select></label>
<?php if($structures): ?><label>Estrutura de componentes<select name="template"><?php foreach($structures as $tid=>$name): ?><option value="<?= $tid ?>" <?= $tid==($_POST['template']??'')?'selected':'' ?>><?= h($name) ?></option><?php endforeach; ?><option value="0" <?= isset($_POST['template']) && $_POST['template']==='0'?'selected':'' ?>>Cadastrar sem componentes</option></select></label><?php endif; ?>
<div class="dialog-actions"><button class="button" type="submit">Cadastrar ativo</button></div></form>
<?php else: ?><p class="note"><?= $compatible?'Cadastre uma linha de produção para utilizar este modelo.':'Este modelo pertence a outro ramo industrial.' ?></p><?php endif; ?></dialog><?php endif; ?>
